MANIFEST = json.loads(zlib.decompress(base64.b64decode(_MANIFEST)).decode())

# UI-P52. The density rules live in one place: the script that applied them.
TIGHTENER = Path("scripts") / "tighten-reference.py"


def repo_root(start: Path) -> Path:
    for d in [start, *start.parents]:
        if (d / "package.json").exists() or (d / ".git").exists():
            return d
    return start


def is_board(rel: str) -> bool:
    return rel.startswith("reference/") and rel.endswith(".html")


def load_tightener(kit: Path):
    """Import design/scripts/tighten-reference.py by path; its file name is not a module name."""
    path = kit / TIGHTENER
    if not path.exists():
        raise SystemExit(f"{path} is missing. The reference boards are written through it (UI-P52): restore it and re-run.")
    spec = importlib.util.spec_from_file_location("tighten_reference", path)
    module = importlib.util.module_from_spec(spec)
    sys.dont_write_bytecode = True  # a restore leaves no __pycache__ in design/scripts/
    spec.loader.exec_module(module)
    return module


def tightened(rel: str, data: bytes, tightener) -> bytes:
    """A board as tighten-reference.py leaves it: tighten() over the inline styles, then its mark."""
    text = tightener.tighten(data.decode("utf-8"), "/mobile/" in rel)
    return text.replace("<head>", "<head>\n" + tightener.MARK, 1).encode("utf-8")


def main() -> int:
    check = "--check" in sys.argv
    here = Path(__file__).resolve().parent
    root = repo_root(here)
    target = root / "design"
    print(f"repository root : {root}")
    print(f"kit             : {target}")

    payload = json.loads(zlib.decompress(base64.b64decode(_BLOB)).decode())
    tightener = None if check else load_tightener(target)

    written, same, missing, differs = 0, 0, [], []
    for rel, b64 in sorted(payload.items()):
        data = base64.b64decode(b64)
        dest = target / rel
        if check:
            if not dest.exists():
                missing.append(rel)
            elif hashlib.sha256(dest.read_bytes()).hexdigest()[:16] != MANIFEST[rel]:
                differs.append(rel)
            else:
                same += 1
            continue
        if is_board(rel):
            data = tightened(rel, data, tightener)
        dest.parent.mkdir(parents=True, exist_ok=True)
        if dest.exists() and dest.read_bytes() == data:
            same += 1
            continue
        dest.write_bytes(data)
        written += 1

    if check:
        print(f"\nmatching : {same}")
        print(f"missing  : {len(missing)}" + (" -> " + ", ".join(missing[:6]) if missing else ""))
        print(f"changed  : {len(differs)}" + (" -> " + ", ".join(differs[:6]) if differs else ""))
        if missing or differs:
            print("\nRun without --check to restore them.")
            return 1
        print("\nThe kit on disk matches this script.")
        return 0

    print(f"\nwritten   : {written}")
    print(f"unchanged : {same}")
    print(f"total     : {written + same} files")
    print("\nNext:")
    print("  git add design && git commit -m 'UI-P00: add design kit'")
    print("  then run design/prompts/UI-P00.md")
    print("\nOpen any design/reference/**/*.html in a browser - it needs nothing else.")
    return 0


